import { parseCloudMetadata, type CloudMetadata } from '../domain/cloud-overlay';

/** Generated by `npm run clouds` (gitignored); the committed sample is the fallback. */
const METADATA_URLS = ['/clouds/latest.json', '/clouds/sample.json'];
/** GOES-19 full-disk scans arrive every 10 minutes. */
export const CLOUD_POLL_MS = 10 * 60 * 1000;

export interface CloudImage {
  readonly meta: CloudMetadata;
  readonly bitmap: ImageBitmap;
  /** True when the committed sample was used because no generated image exists. */
  readonly sample: boolean;
}

async function fetchMetadata(url: string, signal: AbortSignal): Promise<CloudMetadata | null> {
  try {
    const res = await fetch(url, { cache: 'no-store', signal });
    // The Vite dev server answers missing files with index.html, so check the type.
    if (!res.ok || !(res.headers.get('content-type') ?? '').includes('json')) return null;
    return parseCloudMetadata(await res.json());
  } catch (err) {
    if ((err as Error).name === 'AbortError') throw err;
    return null;
  }
}

async function loadBitmap(metaUrl: string, meta: CloudMetadata, signal: AbortSignal): Promise<ImageBitmap> {
  const url = new URL(meta.image, new URL(metaUrl, location.href));
  url.searchParams.set('v', meta.scanStart);
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`cloud image ${res.status}`);
  // Straight alpha and raw values: the shaders treat the image as data.
  return createImageBitmap(await res.blob(), { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
}

/**
 * Polls the cloud metadata and decodes a new image only when the source scan
 * changed. `onImage` receives ownership of the bitmap.
 */
export class CloudFeed {
  private timer: number | undefined;
  private controller: AbortController | null = null;
  private currentKey: string | null = null;

  constructor(
    private readonly onImage: (image: CloudImage) => void,
    private readonly onMissing: () => void,
  ) {}

  start(): void {
    void this.poll();
    this.timer = window.setInterval(() => void this.poll(), CLOUD_POLL_MS);
  }

  stop(): void {
    window.clearInterval(this.timer);
    this.controller?.abort();
  }

  private async poll(): Promise<void> {
    this.controller?.abort();
    const controller = new AbortController();
    this.controller = controller;
    try {
      for (const [i, url] of METADATA_URLS.entries()) {
        const meta = await fetchMetadata(url, controller.signal);
        if (!meta) continue;
        const key = `${url}|${meta.sourceKey}`;
        if (key === this.currentKey) return;
        const bitmap = await loadBitmap(url, meta, controller.signal);
        this.currentKey = key;
        this.onImage({ meta, bitmap, sample: i > 0 });
        return;
      }
      if (this.currentKey === null) this.onMissing();
    } catch (err) {
      if ((err as Error).name !== 'AbortError') console.warn('Cloud layer update failed', err);
    }
  }
}
